const listExpiredDocumentEditLocks = `-- name: ListExpiredDocumentEditLocks :many
SELECT id, organization_id, document_id FROM document_edit_locks
WHERE ended_at IS NULL
  AND expires_at <= now()
  AND (offline_hold_until IS NULL OR offline_hold_until <= now())
ORDER BY expires_at
LIMIT $1
`

type ListExpiredDocumentEditLocksRow struct {
	ID             string `json:"id"`
	OrganizationID string `json:"organization_id"`
	DocumentID     string `json:"document_id"`
}

// tenant: system
// The sweeper: unended tenures whose TTL and hold both ran out, oldest
// first. Each is ended in its own transaction under the document lock.
func (q *Queries) ListExpiredDocumentEditLocks(ctx context.Context, batchLimit int32) ([]ListExpiredDocumentEditLocksRow, error) {
	rows, err := q.db.Query(ctx, listExpiredDocumentEditLocks, batchLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListExpiredDocumentEditLocksRow{}
	for rows.Next() {
		var i ListExpiredDocumentEditLocksRow
		if err := rows.Scan(&i.ID, &i.OrganizationID, &i.DocumentID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

